package com.siam.deviceinfo;import android.os.*;import android.content.*;import android.provider.Settings;import android.net.Uri;import com.siam.deviceinfo.helper.*;import java.util.*;
public class CleanerActivity extends BaseScreenActivity {protected int layout(){return R.layout.activity_cleaner;}protected String title(){return "ক্লিনার ও স্টোরেজ";}public void onCreate(Bundle b){super.onCreate(b);heading("স্টোরেজ");for(Map.Entry<String,Long>e:StorageHelper.summary().entrySet())line(e.getKey(),DeviceInfoHelper.format(e.getValue()));heading("নিরাপদ পরিষ্কার");note("Android কোনো অ্যাপকে অন্য অ্যাপের cache মুছতে, RAM জোর করে খালি করতে বা CPU ঠান্ডা করতে দেয় না। ভুলভাবে এসব দেখানো হয়নি।");action("এই অ্যাপের storage settings",()->{try{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS, Uri.parse("package:"+getPackageName())));}catch(Exception e){note("সেটিংস খোলা যায়নি।");}});action("সিস্টেম Storage settings",()->{try{startActivity(new Intent(Settings.ACTION_INTERNAL_STORAGE_SETTINGS));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}});note("Duplicate photo finder-এর জন্য Photos and videos অনুমতি প্রয়োজন; গোপনীয়তার জন্য এটি এখন স্বয়ংক্রিয়ভাবে স্ক্যান করে না।");}
}
